#include <utility>
int count = 4;
int&& view = std::move(count);
int& alias = view;
// alias и view обозначают тот же объект count.
// Для выбора перегрузки отдельно проверь категорию каждого выражения.

#include <type_traits>
struct Buffer {
  Buffer(const Buffer&);
  Buffer(Buffer&&) noexcept;
};
static_assert(std::is_nothrow_move_constructible_v<Buffer>);
// Это свойство известно на этапе компиляции; его не измеряют запуском кода.
